function createFrameHelmSceneControlTool(
  tokenControls =
    null
) {
  const tools =
    tokenControls?.tools;


  const order =
    Array.isArray(
      tools
    )
      ? tools.length
      : Object.keys(
          tools ??
          {}
        ).length;


  return {
    name:
      FRAME_HELM_SCENE_CONTROL_NAME,

    title:
      MODULE_TITLE,

    icon:
      "fa-solid fa-robot",

    order,

    button:
      true,

    visible:
      true,

    onChange:
      () =>
        openFrameHelmFromFoundryIntegration()
  };
}

